import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Give the test contract (msg.sender for setUp) 100 tokens
        // Since the staking token is address(this), we need a real ERC20 to transfer
        // Deploy a simple ERC20 for testing
        // But the contract expects a specific staking token at address(this).
        // We'll use a different approach: deploy a minimal ERC20 and call stakeAll.
        // However, the staking token is address(this) from setUp, which is the test contract.
        // The test contract does not implement balanceOf, so we need to mock it.
        // Use vm.mockCall to make stakingToken.balanceOf(msg.sender) return 100.
        vm.mockCall(address(c.stakingToken()), abi.encodeWithSignature("balanceOf(address)", address(this)), abi.encode(100));
